      "资源-上锁的缩略图": "WEIZ",
      "----内容----": "",
      "---内容组 1至20---": "",
      "内容-1": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_11\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Chung Linh:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nCon gái của Đoàn Chính Thuần và Cam Bảo\\\\nBảo. Dáng vẻ đáng yêu, tính tình tinh\\\\nnghịch, lanh lợi.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-2": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_12\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Lam Phượng Hoàng:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nGiáo chủ Ngũ Độc Giáo ở Vân Nam. Thích\\\\nnuôi rắn độc, có thể luyện cổ độc của\\\\nngười Miêu trong truyền thuyết.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-3": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_13\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Mộc Uyển Thanh:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nDung mạo tuyệt sắc như ánh trăng non,\\\\nnhư hoa phủ tuyết. Nàng che mặt bằng\\\\nkhăn đen, tính tình mạnh mẽ, đanh đá.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-4": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_14\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Nhạc Linh San:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nTừ nhỏ đã thân thiết với sư huynh Lệnh\\\\nHồ Xung, cùng nhau vui chơi và luyện\\\\nvõ.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-5": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_15\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Ninh Trung Tắc:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nXinh đẹp, ngay thẳng, hào hiệp và trọng\\\\nnghĩa. Một nữ trung hào kiệt hiếm có\\\\ntrong võ lâm.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-6": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_16\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Kha Trấn Ác:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nDùng thiết trượng với trượng pháp cực\\\\nkỳ sắc bén. Giỏi ám khí và cũng là cao\\\\nthủ dùng độc.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-7": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_18\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Ân Ly:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nTính tình bướng bỉnh, cương liệt. Vì\\\\nluyện độc công nên khuôn mặt trở nên\\\\nđen sạm.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-8": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_19\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Vương Ngữ Yên:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nĐọc thuộc bí kíp võ công của các môn\\\\nphái trong thiên hạ, nhìn thấu gần như\\\\nmọi chiêu thức.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-9": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_20\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Quách Phù:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nĐược cha mẹ nuông chiều từ nhỏ nên kiêu\\\\nngạo, ngang ngược, ít nét dịu dàng.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-10": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_21\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Cừu Thiên Xích:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nVõ công cao cường, có biệt hiệu Thiết\\\\nChưởng Liên Hoa.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-11": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_22\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Nhậm Doanh Doanh:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nCon gái duy nhất của Nhậm Ngã Hành,\\\\ngiáo chủ Nhật Nguyệt Thần Giáo. Sau khi\\\\nĐông Phương Bất Bại đoạt quyền, nàng\\\\nđược tôn là Thánh Cô.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-12": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_23\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Đoàn Chính Thuần:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nTrấn Nam Vương nước Đại Lý thời Bắc\\\\nTống. Dáng vẻ uy nghi nhưng bản tính\\\\nphong lưu.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
      "内容-13": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_24\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Công Tôn Chỉ:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nBề ngoài phong thái thanh cao, lễ độ;\\\\nbên trong hiểm độc, bạc tình và phong\\\\nlưu. Một kẻ ngụy quân tử.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
