      "内容-15": "{\"选项名\":\"\",\"---选项内容---\":\"\",\"是否初始显示\":\"true\",\"是否初始锁定\":\"true\",\"选项内容\":\"\\\"\\\"\",\"---画廊内容---\":\"\",\"资源-画廊图片\":\"Face_26\",\"画廊描述内容\":\"\\\"\\\\\\\\fs[20]\\\\\\\\c[14]Tạ Tốn:\\\\\\\\c[0]\\\\\\\\fs[18]\\\\n\\\\nMái tóc vàng cùng tuyệt kỹ Sư Tử Hống\\\\nđem lại biệt hiệu Kim Mao Sư Vương.\\\"\",\"画廊描述内容对齐方式\":\"左对齐\",\"画廊描述内容是否自适应行间距\":\"true\",\"画廊描述内容固定行间距\":\"28\"}",
